// 1000-Result Historical Archive of WinGo 1-Min results
export const SEED_1000_STRING =
  '';

export const SEED_NUMBERS: number[] = Array.from(SEED_1000_STRING).map(Number);

export function getBallSize(num: number): 'BIG' | 'SMALL' {
  return num >= 5 ? 'BIG' : 'SMALL';
}

export function getBallColor(num: number): 'GREEN' | 'RED' | 'VIOLET' {
  if (num === 0 || num === 5) return 'VIOLET';
  if ([1, 3, 7, 9].includes(num)) return 'GREEN';
  return 'RED';
}
